public class Main {
    public static void main(String[] args) {
        int count = 10;
        int postfixResult = count++;

        int steps = 10;
        int prefixResult = ++steps;

        System.out.println("count: " + count + " | postfixResult: " + postfixResult);
        System.out.println("steps: " + steps + " | prefixResult: " + prefixResult);
    }
}

