public class Main {
    public static void main(String[] args) {
        int page = 1;
        System.out.println("Reading Page: " + page++);
        System.out.println("Next Page: " + page);
    }
}

public class Main {
    public static void main(String[] args) {
        int x = 10;
        int y = 10;
        int post = x++;
        int pre = ++y;
        System.out.println("x: " + x + " | post: " + post);
        System.out.println("y: " + y + " | pre: " + pre);
    }
}

public class Main {
    public static void main(String[] args) {
        int seconds = 3;
        System.out.println(seconds--);
        System.out.println(seconds--);
        System.out.println(seconds--);
        System.out.println("Liftoff! Remaining: " + seconds);
    }
}

public class Main {
    public static void main(String[] args) {
        int a = 5;
        int b = a++ + ++a;
        System.out.println("a: " + a + " | b: " + b);
    }
}

public class Main {
    public static void main(String[] args) {
        int p = 8;
        int q = --p - p--;
        System.out.println("p: " + p + " | q: " + q);
    }
}
